import sys
def solve(n, k, prices):
    if k >= n // 2:
        return str(sum(max(prices[i+1]-prices[i],0) for i in range(n-1)))
    dp = [[0]*n for _ in range(k+1)]
    for t in range(1, k+1):
        max_prev = -prices[0]
        for d in range(1, n):
            dp[t][d] = max(dp[t][d-1], prices[d] + max_prev)
            max_prev = max(max_prev, dp[t-1][d] - prices[d])
    return str(dp[k][n-1])

if __name__ == '__main__':
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    prices = list(map(int, data[2:2+n]))
    print(solve(n, k, prices))

